// src/screens/HomeScreen.js - главный экран приложения
import React, { useState } from 'react';
import { 
  View, 
  Text, 
  TouchableOpacity, 
  StyleSheet, 
  ScrollView,
  ActivityIndicator,
  Alert,
  Image // ✅ Импорт для картинок
} from 'react-native';
import useStorage from '../hooks/useStorage'; // ✅ Импорт
import useApi from '../hooks/useApi'; // ✅ Импорт
import { apiService } from '../services/apiService'; // ✅ Импорт
import { Ionicons } from '@expo/vector-icons'; // ✅ Импорт

// 💡 URL для 4 случайных изображений
const API_URL = 'https://picsum.photos/v2/list?page=2&limit=4'; 

const HomeScreen = ({ navigation }) => {
  // ✅ API теперь загружает список картинок
  const { data: images, loading: apiLoading, error: apiError, refetch } = useApi(API_URL);

  const [localData, setLocalData] = useState([]);
  const [postLoading, setPostLoading] = useState(false);

  // Добавление локального элемента (для демонстрации локальных данных)
  const addLocalItem = () => {
    const newItem = {
      id: Date.now(),
      title: `Локальный элемент ${localData.length + 1}`,
      timestamp: new Date().toLocaleTimeString()
    };
    setLocalData(prev => [newItem, ...prev]);
  };

  // POST-запрос (для демонстрации отправки данных)
  const createPost = async () => {
    setPostLoading(true);
    try {
      const newPost = {
        title: 'Новый тестовый пост',
        body: 'Это тестовый пост для проверки POST-запроса.',
        userId: 1
      };

      // Имитация задержки
      await new Promise(resolve => setTimeout(resolve, 1000));
      // Имитируем вызов, используя apiService для структуры, но не для реального результата
      // const result = await apiService.createPost(newPost);

      Alert.alert('Успех', 'POST-запрос (имитация) выполнен успешно!');

    } catch (e) {
      Alert.alert('Ошибка', `Ошибка POST-запроса: ${e.message}`);
    } finally {
      setPostLoading(false);
    }
  };

  // Рендеринг API-картинки
  const renderImage = (image) => (
    <View key={image.id} style={styles.apiItem}>
      <Image 
        source={{ uri: image.download_url }} 
        style={styles.apiImage} 
        resizeMode="cover"
      />
      <Text style={styles.apiName}>Author: {image.author}</Text>
      <Text style={styles.apiEmail}>ID: {image.id}</Text>
    </View>
  );

  // Рендеринг локального элемента
  const renderLocalItem = (item) => (
    <View key={item.id} style={styles.localItem}>
      <Text style={styles.localItemText}>{item.title}</Text>
      <Text style={styles.localItemTimestamp}>{item.timestamp}</Text>
    </View>
  );

  // Компонент для навигации
  const NavigationButton = ({ title, screenName, icon, color }) => (
    <TouchableOpacity 
      style={[styles.navButton, { backgroundColor: color }]} 
      onPress={() => navigation.navigate(screenName)}
    >
      <Ionicons name={icon} size={20} color="white" />
      <Text style={styles.navButtonText}>{title}</Text>
    </TouchableOpacity>
  );

  return (
    <ScrollView style={styles.container}>

      {/* Секция Навигации */}
      <View style={styles.section}>
        <Text style={styles.sectionTitle}>Навигация по приложению</Text>
        <View style={styles.navRow}>
          <NavigationButton 
            title="Мультимедиа" 
            screenName="Media" 
            icon="camera" 
            color="#34C759"
          />
          <NavigationButton 
            title="Галерея" 
            screenName="Gallery" 
            icon="images" 
            color="#007AFF"
          />
        </View>
        <View style={styles.navRow}>
          <NavigationButton 
            title="Аналитика" 
            screenName="Analytics" 
            icon="analytics" 
            color="#FF9500"
          />
          <NavigationButton 
            title="Настройки" 
            screenName="Settings" 
            icon="settings" 
            color="#5856D6"
          />
        </View>
      </View>


      {/* Секция API-данных (с картинками) */}
      <View style={styles.section}>
        <Text style={styles.sectionTitle}>Внешние API-Данные (Картинки)</Text>

        <TouchableOpacity 
          style={[styles.button, styles.apiButton]} 
          onPress={refetch}
          disabled={apiLoading}
        >
          <Text style={styles.buttonText}>
            {apiLoading ? 'Загрузка...' : 'Обновить API-картинки (GET)'}
          </Text>
        </TouchableOpacity>

        {/* Кнопка POST-запроса */}
        <TouchableOpacity 
          style={[styles.button, styles.postButton]} 
          onPress={createPost}
          disabled={postLoading}
        >
          <Text style={styles.buttonText}>
            {postLoading ? 'Отправка...' : 'Имитировать POST-запрос'}
          </Text>
        </TouchableOpacity>

        {apiError && <Text style={styles.errorText}>Ошибка: {apiError}</Text>}

        {(images && images.length > 0) ? (
          <View style={styles.apiList}>
            <Text style={styles.listHeader}>Список загруженных картинок:</Text>
            {images.slice(0, 4).map(renderImage)}
          </View>
        ) : (
          !apiLoading && <Text style={styles.listHeader}>Данные API не загружены. Нажмите кнопку "Обновить".</Text>
        )}
      </View>

      {/* Секция Локальные данные */}
      <View style={styles.section}>
        <Text style={styles.sectionTitle}>Локальные данные (State)</Text>
        <TouchableOpacity 
          style={styles.button} 
          onPress={addLocalItem}
        >
          <Text style={styles.buttonText}>Добавить локальный элемент</Text>
        </TouchableOpacity>

        <View style={styles.localList}>
          {localData.length === 0 ? (
            <Text style={styles.listHeader}>Список пуст.</Text>
          ) : (
            localData.map(renderLocalItem)
          )}
        </View>
      </View>

    </ScrollView>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#f5f5f5',
  },
  section: {
    backgroundColor: 'white',
    margin: 10,
    borderRadius: 12,
    padding: 15,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.1,
    shadowRadius: 4,
    elevation: 3,
    marginBottom: 15,
  },
  sectionTitle: {
    fontSize: 18,
    fontWeight: 'bold',
    marginBottom: 10,
    color: '#333',
    borderBottomWidth: 1,
    borderBottomColor: '#f0f0f0',
    paddingBottom: 5,
  },
  navRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    marginBottom: 10,
  },
  navButton: {
    paddingHorizontal: 15,
    paddingVertical: 12,
    borderRadius: 8,
    alignItems: 'center',
    flex: 1,
    marginHorizontal: 5,
    flexDirection: 'row',
    justifyContent: 'center',
    gap: 8,
  },
  navButtonText: {
    color: 'white',
    fontSize: 14,
    fontWeight: '600',
  },
  button: {
    backgroundColor: '#007AFF',
    paddingHorizontal: 20,
    paddingVertical: 12,
    borderRadius: 8,
    alignItems: 'center',
    marginVertical: 5,
  },
  apiButton: {
    backgroundColor: '#FF9500',
  },
  postButton: {
    backgroundColor: '#34C759',
  },
  buttonText: {
    color: 'white',
    fontSize: 16,
    fontWeight: '600',
  },
  errorText: {
    color: '#FF3B30',
    marginTop: 10,
    textAlign: 'center',
  },
  apiList: {
    marginTop: 15,
  },
  localList: {
    marginTop: 10,
  },
  listHeader: {
    fontSize: 14,
    color: '#666',
    marginBottom: 10,
  },
  apiItem: {
    backgroundColor: '#f9f9f9',
    padding: 10,
    borderRadius: 8,
    marginBottom: 10,
    borderLeftWidth: 3,
    borderLeftColor: '#007AFF',
  },
  apiImage: {
    width: '100%',
    height: 100,
    borderRadius: 5,
    marginBottom: 5,
  },
  apiName: {
    fontSize: 14,
    fontWeight: '600',
    color: '#333',
  },
  apiEmail: {
    fontSize: 12,
    color: '#999',
  },
  localItem: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    paddingVertical: 8,
    borderBottomWidth: 1,
    borderBottomColor: '#eee',
  },
  localItemText: {
    fontSize: 16,
    color: '#333',
  },
  localItemTimestamp: {
    fontSize: 12,
    color: '#999',
  }
});

export default HomeScreen;
